package app.multimin.ui;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.regex.*;
/** Release notes are displayed as inert text, never interpreted as HTML or commands. */
final class UpdateDialog {
 static String plain(String markdown){return markdown.replaceAll("(?m)^#{1,6}\\s+","").replaceAll("\\[([^\\]]+)\\]\\([^)]*\\)","$1").replace("**","").replace("`","").trim();}
 static String summary(String notes){Matcher section=Pattern.compile("(?ims)^##\\s+(?:Plain English|Simple(?: changelog)?|Summary)\\s*\\R(.*?)(?=^##\\s|\\z)").matcher(notes);if(section.find())return plain(section.group(1));String text=notes.replaceFirst("(?m)^# [^\\r\\n]*\\R*","").trim();int end=text.indexOf("\n\n");return text.isBlank()?"Release notes were not supplied for this update.":plain(end>0?text.substring(0,end):text);}
 static String detailed(String notes){Matcher section=Pattern.compile("(?ims)^##\\s+(?:Detailed|Technical(?: changelog)?)\\s*\\R(.*?)(?=^##\\s|\\z)").matcher(notes);return plain(section.find()?section.group(1):notes.isBlank()?"No detailed release notes supplied.":notes);}
 static boolean offer(JFrame owner,Palette palette,String current,String next,String notes){
  JDialog dialog=new JDialog(owner,"MultiMini update",true);dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);dialog.setMinimumSize(new Dimension(500,350));dialog.setSize(590,430);dialog.setResizable(true);
  JPanel body=new JPanel(new BorderLayout(0,14));body.setBackground(palette.background);body.setBorder(new EmptyBorder(16,18,14,18));
  JPanel heading=new JPanel(new GridLayout(0,1,0,5));heading.setOpaque(false);JLabel title=new JLabel("Update available");title.setFont(new Font(Font.DIALOG,Font.BOLD,16));title.setForeground(palette.text);heading.add(title);
  JLabel versions=new JLabel(current+"  →  "+next);versions.setFont(new Font(Font.DIALOG,Font.PLAIN,17));versions.setForeground(palette.text);heading.add(versions);body.add(heading,BorderLayout.NORTH);
  JPanel center=new JPanel(new BorderLayout(0,10));center.setOpaque(false);JPanel tabs=new JPanel(new FlowLayout(FlowLayout.LEFT,0,0));tabs.setOpaque(false);CardLayout cards=new CardLayout();JPanel content=new JPanel(cards);content.setOpaque(false);ButtonGroup group=new ButtonGroup();
  String[] labels={"Plain English","Detailed"};String[] texts={summary(notes),detailed(notes)};
  for(int i=0;i<labels.length;i++){String name=labels[i];JToggleButton button=new JToggleButton(name){@Override protected void paintComponent(Graphics graphics){setForeground(isSelected()?palette.text:palette.muted);super.paintComponent(graphics);if(isSelected()){graphics.setColor(palette.accent);graphics.fillRect(8,getHeight()-2,getWidth()-16,2);}}};button.setOpaque(false);button.setContentAreaFilled(false);button.setBorderPainted(false);button.setFocusPainted(false);button.setBorder(new EmptyBorder(7,10,7,10));button.setFont(new Font(Font.DIALOG,Font.PLAIN,12));button.setPreferredSize(new Dimension(i==0?110:88,32));group.add(button);button.setSelected(i==0);button.addActionListener(e->cards.show(content,name));tabs.add(button);JTextArea text=new JTextArea(texts[i]);text.setFont(new Font(Font.DIALOG,Font.PLAIN,13));text.setLineWrap(true);text.setWrapStyleWord(true);text.setEditable(false);text.setBackground(palette.controlSurface());text.setForeground(palette.text);text.setSelectionColor(palette.accent);text.setSelectedTextColor(palette.selectionText());text.setBorder(new EmptyBorder(10,12,10,12));text.setCaretPosition(0);JScrollPane scroll=new JScrollPane(text);scroll.setBorder(BorderFactory.createLineBorder(palette.line));ModernUi.scroll(scroll.getVerticalScrollBar(),palette);scroll.getVerticalScrollBar().setUnitIncrement(20);content.add(scroll,name);}
  center.add(tabs,BorderLayout.NORTH);center.add(content);body.add(center);JPanel footer=new JPanel(new BorderLayout(12,12));footer.setOpaque(false);footer.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(1,0,0,0,palette.line),new EmptyBorder(10,0,0,0)));JLabel note=new JLabel("MultiMini will restart after updating.");note.setFont(new Font(Font.DIALOG,Font.PLAIN,11));note.setForeground(palette.muted);footer.add(note,BorderLayout.NORTH);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));actions.setOpaque(false);boolean[] accepted={false};JButton later=new ModernButton("Remind me later",null,palette,false),update=new ModernButton("Update now",null,palette,true);later.setToolTipText("Ask again the next time MultiMini starts");later.addActionListener(e->dialog.dispose());update.addActionListener(e->{accepted[0]=true;dialog.dispose();});actions.add(later);actions.add(update);footer.add(actions);body.add(footer,BorderLayout.SOUTH);dialog.setContentPane(body);dialog.getRootPane().setDefaultButton(update);dialog.getRootPane().registerKeyboardAction(e->dialog.dispose(),KeyStroke.getKeyStroke("ESCAPE"),JComponent.WHEN_IN_FOCUSED_WINDOW);dialog.setLocationRelativeTo(owner);dialog.setVisible(true);return accepted[0];
 }
}
